<?php
require __DIR__ . '/config/database.php';
require __DIR__ . '/includes/helpers.php';
$vehicleId = (int)($_GET['vehicle_id'] ?? $_POST['vehicle_id'] ?? 0);
$vehicle = null;
$stmt = $conn->prepare('SELECT id, name, year, category, image_url FROM vehicles WHERE id = ? AND is_available = 1');
$stmt->bind_param('i', $vehicleId);
$stmt->execute();
$vehicle = $stmt->get_result()->fetch_assoc();
$stmt->close();
if (!$vehicle) { http_response_code(404); die('Vehicle not found. <a href="index.php">Return home</a>'); }
$error = $_GET['error'] ?? '';
?>
